(()=>{const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let host,company='',data=null,readId='',pending=null,saving=false,dialog;const customer=id=>data?.customers.find(row=>row.id===id)?.name||id;
 let currentDispatchStaff=null,dispatchSerial=0,dispatchRecovery=0;
 function resumeCurrentDispatch(staff,request){
  if(!request||pending||saving||dialog?.open)return;pending=JSON.parse(JSON.stringify(request));currentDispatchStaff=staff;
  if(!dialog){dialog=document.createElement('dialog');dialog.style.width='480px';document.body.appendChild(dialog);dialog.addEventListener('cancel',event=>{if(pending||saving)event.preventDefault();});}
  dialog.innerHTML='<div class="dialog-header"><h2>Pending Dispatch 待确认出库</h2></div><div class="dialog-body"><p>'+esc(request.input.id)+'</p><p>'+esc(request.requestId)+'</p><p>Retry the original save. Do not register the same dispatch again.<br>请重试原保存，不要重复登记同一次出库。</p><p data-error role="alert"></p></div><footer><button data-save class="primary">Retry same dispatch 重试原出库</button></footer>';
  dialog.querySelector('[data-save]').onclick=send;dialog.showModal();
 }
 function recoverCurrentDispatch(){
  if(pending||saving||dialog?.open||!window.warehouseCurrentDispatch)return;const selected=company,attempt=++dispatchRecovery;
  window.warehouseCurrentDispatch.recover(company).then(result=>{if(company===selected&&attempt===dispatchRecovery)resumeCurrentDispatch(result.staff,result.request);})
   .catch(()=>{if(company===selected&&attempt===dispatchRecovery&&host)host.querySelector('[data-dispatch-error]').textContent='Original dispatch recovery unconfirmed. Keep this tab and check login. 原出库恢复尚未确认，请保留此页并核对登录。';});
 }
 function currentDispatchResult(message){
  if(pending?.stockProtocol!==1)return false;const original=pending,result=message.result;
  if(message.ok&&result?.ok===false&&result.pending===true&&result.requestId===original.requestId&&saving&&['BEFORE','APPLY','VERIFY'].includes(result.phase)&&Number.isSafeInteger(result.completedCount)&&Number.isSafeInteger(result.totalRecords)&&result.totalRecords>0&&result.completedCount>=0&&result.completedCount<=result.totalRecords){
   saving=false;dialog.querySelectorAll('button,input,textarea').forEach(el=>el.disabled=false);dialog.querySelector('[data-error]').textContent='Saving dispatch 保存出库中… '+result.completedCount+' / '+result.totalRecords;const serial=dispatchSerial;
   setTimeout(()=>{if(pending===original&&!saving&&serial===dispatchSerial)send();},250);return true;
  }
  dispatchSerial++;saving=false;dialog.querySelectorAll('button,input,textarea').forEach(el=>el.disabled=false);
  if(!(message.ok&&result?.ok===true&&result.requestId===original.requestId&&result.company===company&&result.shipmentId===original.input.id&&result.status==='DISPATCHED'&&Number.isSafeInteger(result.stockGeneration)&&result.stockGeneration>original.stockGeneration)){
   dialog.querySelector('[data-error]').textContent='Dispatch result unconfirmed. Retry the original save. 出库结果尚未确认，请重试原保存。';return true;
  }
  try{window.warehouseCurrentDispatch.clear(original,currentDispatchStaff);}catch(_){dialog.querySelector('[data-error]').textContent='Dispatch confirmed; cache cleanup pending. Retry original save. 出库已确认，暂存清理待核对，请重试原保存。';return true;}
  pending=null;data=null;dialog.close();paint();request();return true;
 }
 window.addEventListener('beforeunload',event=>{if(pending?.stockProtocol===1){event.preventDefault();event.returnValue='';}});
 function request(){if(saving||pending||data?.stockCurrent&&dialog?.open)return;readId=crypto.randomUUID();parent.postMessage({type:'FULFILMENT_READ_REQUEST',company,requestId:readId},'*');}
 function paint(){if(!host)return;host.innerHTML='<section class="panel"><h2 style="padding:10px;font-size:13px">Customer Dispatch 客户发货</h2><p data-dispatch-error class="account-notice"></p><div class="table-scroll"><table><thead><tr><th>Customer 客户</th><th>Sales Invoice 销售发票</th><th>Barcode · Item 产品</th><th>Qty 箱数</th><th>Status 状态</th><th>Dispatch 发货</th></tr></thead><tbody>'+(data?.shipments||[]).filter(row=>row.status!=='CANCELLED'&&row.status!=='DISPATCHED').map(row=>'<tr><td>'+esc(customer(row.customerId))+'</td><td>'+esc(row.invoice?.number||'Awaiting Support 等待文员开票')+'</td><td>'+row.lines.map(line=>esc(line.barcode)+' · '+esc(line.name)).join('<br>')+'</td><td>'+row.lines.reduce((sum,line)=>sum+line.quantity,0)+'</td><td>'+esc(row.status==='INVOICED'?'Ready to dispatch 可安排发货':'Blocked by Support 等待文员开票')+'</td><td>'+(row.status==='INVOICED'&&data.permissions.dispatch?'<button data-dispatch="'+esc(row.id)+'">Confirm Dispatch 确认已发货</button>':'<span style="color:#F58A00">●</span>')+'</td></tr>').join('')+'</tbody></table></div></section>';host.querySelectorAll('[data-dispatch]').forEach(button=>button.onclick=()=>open(button.dataset.dispatch));}
 function open(id){if(pending?.stockProtocol===1){if(!dialog.open)dialog.showModal();return;}const row=data.shipments.find(row=>row.id===id);if(!dialog){dialog=document.createElement('dialog');dialog.style.width='480px';document.body.appendChild(dialog);dialog.addEventListener('cancel',event=>{if(pending||saving)event.preventDefault();});}dialog.innerHTML='<div class="dialog-header"><div><h2>Confirm Dispatch 确认实际发货</h2><strong>'+esc(customer(row.customerId))+' · '+esc(row.invoice.number)+'</strong></div></div><div class="dialog-body"><p>'+row.lines.map(line=>esc(line.barcode)+' · '+line.quantity+' CTN').join('<br>')+'</p><label>Container / DO reference · 柜号或出库单<input data-reference maxlength="120"></label><label>Reason 说明<textarea data-reason rows="2" maxlength="2000"></textarea></label><label><input data-confirm type="checkbox">Goods physically dispatched 确认货物已实际发出</label><p data-error role="alert"></p></div><footer><button data-close>Cancel 取消</button><button data-save class="primary">Confirm 确认</button></footer>';dialog.querySelector('[data-close]').onclick=()=>{if(!pending&&!saving)dialog.close();};dialog.querySelector('[data-save]').onclick=()=>{if(saving)return;if(!pending){const reference=dialog.querySelector('[data-reference]').value.trim(),reason=dialog.querySelector('[data-reason]').value.trim();if(!reference||!reason||!dialog.querySelector('[data-confirm]').checked){dialog.querySelector('[data-error]').textContent='请填写出库参考、说明，并确认实际已发货。';return;}pending={type:'FULFILMENT_SAVE_REQUEST',company,requestId:crypto.randomUUID(),input:{action:'DISPATCH',id:row.id,version:data.version,reference,reason}};if(data.stockCurrent)pending=JSON.parse(JSON.stringify({...pending,stockProtocol:1,stockBuild:data.stockCurrent.stockBuild,stockGeneration:data.stockCurrent.stockGeneration,stockIdentity:{staffId:data.staff.staffId,memberId:data.staff.memberId}}));}send();};dialog.showModal();}
 function send(){if(saving||!pending)return;
  if(pending.stockProtocol===1){try{window.warehouseCurrentDispatch.retain(pending,currentDispatchStaff);}catch(_){dialog.querySelector('[data-error]').textContent='Dispatch not sent: cache confirmation required. 出库尚未发送，请核对浏览器暂存。';return;}}
  saving=true;dialog.querySelectorAll('button,input,textarea').forEach(el=>el.disabled=true);parent.postMessage(pending,'*');const current=pending,serial=++dispatchSerial;setTimeout(()=>{if(pending===current&&(pending.stockProtocol!==1||serial===dispatchSerial)){saving=false;dialog.querySelectorAll('button,input,textarea').forEach(el=>el.disabled=false);dialog.querySelector('[data-error]').textContent='Save not confirmed 尚未确认，请重试同一次操作';}},30000);}
 window.warehouseDispatch={isBusy:()=>Boolean(pending||saving||dialog?.open),render(element,value){host=element;if(company!==value){company=value;data=null;readId='';}paint();if(!data&&!readId)request();},refresh:request};
 window.addEventListener('message',event=>{const m=event.data||{};if(event.source!==parent||m.company!==company)return;if(m.type==='FULFILMENT_READ_RESULT'&&m.requestId===readId){readId='';if(m.ok){
  if(pending?.stockProtocol===1||data?.stockCurrent&&dialog?.open)return;
  if(m.result?.stockCurrent!==undefined){const meta=m.result.stockCurrent;
   if(meta.schema!=='CURRENT_STOCK_V2'||meta.stockProtocol!==1||!meta.stockBuild||!Number.isSafeInteger(meta.stockGeneration)||meta.stockGeneration<0||!m.result.staff?.staffId||!m.result.staff.memberId){if(host)host.querySelector('[data-dispatch-error]').textContent='Current dispatch workspace unconfirmed 当前出库资料尚未确认';return;}
   currentDispatchStaff=m.result.staff;dispatchRecovery++;
   try{const cached=window.warehouseCurrentDispatch.pending(company,currentDispatchStaff);if(cached)resumeCurrentDispatch(currentDispatchStaff,cached);}catch(_){if(host)host.querySelector('[data-dispatch-error]').textContent='Original dispatch cache unavailable. Do not register again. 原出库暂存无法核对，请勿重新登记。';return;}
  }else currentDispatchStaff=null;
  data=m.result;paint();
 }else{if(host)host.querySelector('[data-dispatch-error]').textContent=m.error||'Read failed';recoverCurrentDispatch();}}if(m.type==='FULFILMENT_SAVE_RESULT'&&m.requestId===pending?.requestId){if(currentDispatchResult(m))return;saving=false;dialog.querySelectorAll('button,input,textarea').forEach(el=>el.disabled=false);if(m.ok&&m.result?.ok){pending=null;dialog.close();request();}else{const error=m.error||m.result?.error||'Save not confirmed';dialog.querySelector('[data-error]').textContent=error;if(/changed|required|not authorized/.test(error))pending=null;}}});
})();
